/**
 * Structured data (JSON-LD) for SEO — Organization, WebSite, FAQPage.
 * Used in root layout.
 */

export type JsonLd = Record<string, unknown>;

const siteUrl = process.env.NEXT_PUBLIC_SITE_URL ?? "https://getsmsnow.com";

export function getOrganizationJsonLd(): JsonLd {
  return {
    "@context": "https://schema.org",
    "@type": "Organization",
    "@id": `${siteUrl}/#organization`,
    name: "GetSMSNow",
    url: siteUrl,
    logo: `${siteUrl}/logo.png`,
    description:
      "Get SMS instantly with GetSMSNow! Use secure temporary numbers for quick verification and online privacy.",
    sameAs: ["https://t.me/GetSMSNow"],
  };
}

export function getWebSiteJsonLd(): JsonLd {
  return {
    "@context": "https://schema.org",
    "@type": "WebSite",
    name: "GetSMSNow",
    url: siteUrl,
    description: "Receive SMS online with temporary phone numbers. Fast, secure, and reliable.",
    publisher: { "@id": `${siteUrl}/#organization` },
    potentialAction: {
      "@type": "SearchAction",
      target: { "@type": "EntryPoint", urlTemplate: `${siteUrl}/sms-activations?service={search_term_string}` },
      "query-input": "required name=search_term_string",
    },
  };
}

const faqItems = [
  {
    question: "What is GetSMSNow?",
    answer:
      "GetSMSNow is a service that provides temporary phone numbers for receiving SMS online. These numbers can be used for various purposes, including account verification, online registrations, and more.",
  },
  {
    question: "How does GetSMSNow work?",
    answer:
      "GetSMSNow offers temporary phone numbers from various countries that you can use to receive SMS messages online. Simply choose a number, use it to receive a verification code or message, and view the SMS directly on our platform.",
  },
  {
    question: "How do I start using a number with GetSMSNow?",
    answer:
      "To use a number, visit the GetSMSNow website, top up your balance, select country, service, choose your preferred period Activation or Rent and press the Get Number button.",
  },
  {
    question: "Can I choose a number from a specific country?",
    answer:
      "Yes, GetSMSNow allows you to select a number from a specific country depending on availability.",
  },
  {
    question: "How long can I use a temporary number?",
    answer:
      "The duration depends on the period you choose. Some numbers are available for short term use, while others can be rented for longer periods.",
  },
  {
    question: "Is my privacy protected when using GetSMSNow?",
    answer:
      "Yes, GetSMSNow prioritizes your privacy. The service allows you to use temporary numbers instead of your personal phone number, reducing the risk of unwanted contacts and protecting your personal information.",
  },
];

export function getFaqJsonLd(): JsonLd {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqItems.map((item) => ({
      "@type": "Question",
      name: item.question,
      acceptedAnswer: {
        "@type": "Answer",
        text: item.answer,
      },
    })),
  };
}

export function getStructuredDataScripts(): JsonLd[] {
  const organization = getOrganizationJsonLd();
  const website = getWebSiteJsonLd();
  const faq = getFaqJsonLd();
  return [organization, website, faq];
}
