import type { Metadata } from "next";
import "@/app/globals.css";
import Navbar from "@/components/layout/Navbar";
import Footer from "@/components/layout/Footer";
import { Inter } from "next/font/google";
import ClientBody from "./ClientBody";
import { ThemeProvider } from "@/components/theme/ThemeProvider";
import { getStructuredDataScripts } from "@/data/structured-data";

const inter = Inter({
  subsets: ["latin"],
  variable: "--font-sans",
});

const siteUrl = process.env.NEXT_PUBLIC_SITE_URL ?? "https://getsmsnow.com";
const ogImageUrl = `${siteUrl}/og.png`;

export const metadata: Metadata = {
  metadataBase: new URL(siteUrl),
  title: {
    default: "GetSMSNow - Receive SMS Online",
    template: "%s | GetSMSNow",
  },
  description:
    "Get SMS instantly with GetSMSNow! Use secure temporary numbers for quick verification and online privacy. Simple, fast, and reliable.",
  keywords: ["SMS", "receive SMS online", "temporary number", "virtual number", "verification", "GetSMSNow"],
  authors: [{ name: "GetSMSNow" }],
  icons: {
    icon: [{ url: "/favicon.ico", sizes: "any" }],
    apple: "/apple-touch-icon.png",
  },
  openGraph: {
    type: "website",
    locale: "en_US",
    url: siteUrl,
    siteName: "GetSMSNow",
    title: "GetSMSNow - Receive SMS Online",
    description: "Use secure temporary numbers for quick verification and online privacy.",
    images: [
      {
        url: ogImageUrl,
        width: 1200,
        height: 630,
        alt: "GetSMSNow - Receive SMS Online",
      },
    ],
  },
  twitter: {
    card: "summary_large_image",
    title: "GetSMSNow - Receive SMS Online",
    description: "Use secure temporary numbers for quick verification and online privacy.",
    images: [ogImageUrl],
  },
  robots: {
    index: true,
    follow: true,
  },
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const structuredData = getStructuredDataScripts();

  return (
    <html lang="en" suppressHydrationWarning>
      <body
        className={`min-h-screen bg-background antialiased ${inter.variable} font-sans`}
      >
        {structuredData.map((data, i) => (
          <script
            key={i}
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: JSON.stringify(data) }}
          />
        ))}
        <ThemeProvider defaultTheme="system">
          <div className="relative flex min-h-screen flex-col">
            <Navbar />
            <main className="flex-1">
              {children}
            </main>
            <Footer />
          </div>
          <ClientBody />
        </ThemeProvider>
      </body>
    </html>
  );
}
